"""AI-powered article writing using Claude."""

from dataclasses import dataclass, field

import anthropic

from .research import ResearchResult


@dataclass
class ArticleOutline:
    """An article outline generated by AI."""

    title: str
    sections: list[str]
    key_points: list[str]
    target_audience: str
    estimated_word_count: int


@dataclass
class GeneratedArticle:
    """A generated article with metadata."""

    title: str
    content: str
    outline: ArticleOutline | None = None
    sources: list[str] = field(default_factory=list)
    word_count: int = 0

    def __post_init__(self):
        if not self.word_count:
            self.word_count = len(self.content.split())


class AIArticleWriter:
    """AI-powered article writer using Claude."""

    def __init__(
        self,
        api_key: str,
        model: str = "claude-sonnet-4-20250514",
        min_words: int = 800,
        max_words: int = 2000,
    ):
        """Initialize the AI article writer.

        Args:
            api_key: Anthropic API key.
            model: Claude model to use.
            min_words: Minimum word count for articles.
            max_words: Maximum word count for articles.
        """
        self.client = anthropic.Anthropic(api_key=api_key)
        self.model = model
        self.min_words = min_words
        self.max_words = max_words

    def generate_outline(
        self,
        topic: str,
        research_results: list[ResearchResult],
        audience: str = "general educators and teachers",
        article_type: str = "informative",
    ) -> ArticleOutline:
        """Generate an article outline based on research.

        Args:
            topic: The article topic.
            research_results: Research results to inform the outline.
            audience: Target audience description.
            article_type: Type of article (informative, how-to, opinion, etc.)

        Returns:
            ArticleOutline with structure for the article.
        """
        research_context = "\n\n".join(r.to_context() for r in research_results)

        prompt = f"""Based on the following research, create an outline for an education article.

Topic: {topic}
Target Audience: {audience}
Article Type: {article_type}
Target Word Count: {self.min_words}-{self.max_words} words

Research:
{research_context}

Please provide an outline in the following format:

TITLE: [Suggested article title]

SECTIONS:
1. [Section 1 title]
2. [Section 2 title]
3. [Section 3 title]
(continue as needed)

KEY POINTS:
- [Key point 1]
- [Key point 2]
- [Key point 3]
(continue as needed)

Keep the outline focused and practical for educators."""

        response = self.client.messages.create(
            model=self.model,
            max_tokens=1000,
            messages=[{"role": "user", "content": prompt}],
        )

        outline_text = response.content[0].text
        return self._parse_outline(outline_text, audience)

    def _parse_outline(self, text: str, audience: str) -> ArticleOutline:
        """Parse the AI-generated outline text into an ArticleOutline."""
        lines = text.strip().split("\n")

        title = ""
        sections = []
        key_points = []

        current_section = None

        for line in lines:
            line = line.strip()
            if not line:
                continue

            if line.startswith("TITLE:"):
                title = line.replace("TITLE:", "").strip()
            elif line == "SECTIONS:":
                current_section = "sections"
            elif line == "KEY POINTS:":
                current_section = "key_points"
            elif current_section == "sections" and line[0].isdigit():
                # Remove numbering
                section = line.split(".", 1)[-1].strip() if "." in line else line
                sections.append(section)
            elif current_section == "key_points" and line.startswith("-"):
                key_points.append(line[1:].strip())

        return ArticleOutline(
            title=title or "Untitled Article",
            sections=sections,
            key_points=key_points,
            target_audience=audience,
            estimated_word_count=self.max_words,
        )

    def write_article(
        self,
        topic: str,
        research_results: list[ResearchResult],
        outline: ArticleOutline | None = None,
        style_guide: str | None = None,
    ) -> GeneratedArticle:
        """Write a complete article based on research.

        Args:
            topic: The article topic.
            research_results: Research results to inform the article.
            outline: Optional pre-generated outline.
            style_guide: Optional style guidelines.

        Returns:
            GeneratedArticle with the complete article.
        """
        # Generate outline if not provided
        if not outline:
            outline = self.generate_outline(topic, research_results)

        research_context = "\n\n".join(r.to_context() for r in research_results)

        # Collect source URLs
        sources = []
        for result in research_results:
            for source in result.sources:
                if source.url not in sources:
                    sources.append(source.url)

        style_instructions = style_guide or """
- Write in a professional but accessible tone
- Use clear, concise language
- Include practical examples where relevant
- Structure content with clear headings
- Make content actionable for educators"""

        prompt = f"""Write a complete education article based on the following:

TOPIC: {topic}

OUTLINE:
Title: {outline.title}
Sections: {', '.join(outline.sections)}
Key Points: {', '.join(outline.key_points)}

TARGET AUDIENCE: {outline.target_audience}
WORD COUNT: {self.min_words}-{self.max_words} words

RESEARCH SOURCES:
{research_context}

STYLE GUIDELINES:
{style_instructions}

FORMATTING INSTRUCTIONS:
- Use markdown formatting
- Start with a # heading for the title
- Use ## for main sections
- Use ### for subsections if needed
- Use bullet points and numbered lists where appropriate
- Do not include "Sources" or "References" section - that will be added separately

Write the complete article now:"""

        response = self.client.messages.create(
            model=self.model,
            max_tokens=4000,
            messages=[{"role": "user", "content": prompt}],
        )

        article_content = response.content[0].text

        return GeneratedArticle(
            title=outline.title,
            content=article_content,
            outline=outline,
            sources=sources,
        )

    def improve_article(
        self,
        article: GeneratedArticle,
        feedback: str,
    ) -> GeneratedArticle:
        """Improve an article based on feedback.

        Args:
            article: The article to improve.
            feedback: Specific feedback for improvements.

        Returns:
            Improved GeneratedArticle.
        """
        prompt = f"""Please improve the following education article based on the feedback provided.

CURRENT ARTICLE:
{article.content}

FEEDBACK:
{feedback}

Please rewrite the article incorporating the feedback while maintaining:
- The overall structure and key points
- Professional but accessible tone
- Markdown formatting

Write the improved article:"""

        response = self.client.messages.create(
            model=self.model,
            max_tokens=4000,
            messages=[{"role": "user", "content": prompt}],
        )

        improved_content = response.content[0].text

        return GeneratedArticle(
            title=article.title,
            content=improved_content,
            outline=article.outline,
            sources=article.sources,
        )

    def generate_title_suggestions(
        self,
        topic: str,
        research_results: list[ResearchResult],
        count: int = 5,
    ) -> list[str]:
        """Generate multiple title suggestions for an article.

        Args:
            topic: The article topic.
            research_results: Research results for context.
            count: Number of title suggestions to generate.

        Returns:
            List of title suggestions.
        """
        research_context = "\n\n".join(r.to_context() for r in research_results[:2])

        prompt = f"""Generate {count} compelling title options for an education article about:

Topic: {topic}

Research Context:
{research_context}

Requirements:
- Titles should be engaging and clear
- Appropriate for education professionals
- Between 5-12 words each
- Varied styles (some question-based, some statement-based, etc.)

List {count} title options, one per line, numbered:"""

        response = self.client.messages.create(
            model=self.model,
            max_tokens=500,
            messages=[{"role": "user", "content": prompt}],
        )

        # Parse titles from response
        titles = []
        for line in response.content[0].text.split("\n"):
            line = line.strip()
            if line and line[0].isdigit():
                # Remove numbering and clean up
                title = line.split(".", 1)[-1].strip() if "." in line else line
                title = title.strip('"\'')
                if title:
                    titles.append(title)

        return titles[:count]
